package com.acme.tokenservice.controller;

import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpStatus;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.util.Base64;
import java.security.MessageDigest;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@RestController
@RequestMapping("/api/v2/tokens")
public class TokenDecryptionController {

    private static final Logger log = LoggerFactory.getLogger(TokenDecryptionController.class);
    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final byte[] SECRET_KEY = "ThisIs128BitKey!".getBytes();

    @PostMapping("/validate")
    public ResponseEntity<?> validateToken(@RequestBody TokenRequest request) {
        try {
            String decrypted = decryptToken(request.getEncryptedToken());
            if (decrypted == null) {
                return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(new ErrorResponse("INVALID_TOKEN", "Token could not be processed"));
            }
            // Verify token structure: userId|timestamp|nonce
            String[] parts = decrypted.split("\\|");
            if (parts.length != 3) {
                return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(new ErrorResponse("MALFORMED_TOKEN", "Token structure invalid"));
            }
            return ResponseEntity.ok(new TokenResponse(parts[0], Long.parseLong(parts[1])));
        } catch (javax.crypto.BadPaddingException e) {
            log.warn("Padding validation failed for token from request");
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorResponse("PADDING_ERROR", "Token integrity check failed"));
        } catch (javax.crypto.IllegalBlockSizeException e) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorResponse("BLOCK_SIZE_ERROR", "Token length invalid"));
        } catch (Exception e) {
            log.error("Unexpected error during token validation", e);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(new ErrorResponse("INTERNAL_ERROR", "An unexpected error occurred"));
        }
    }

    private String decryptToken(String encryptedToken) throws Exception {
        byte[] combined = Base64.getDecoder().decode(encryptedToken);
        byte[] iv = new byte[16];
        byte[] ciphertext = new byte[combined.length - 16];
        System.arraycopy(combined, 0, iv, 0, 16);
        System.arraycopy(combined, 16, ciphertext, 0, ciphertext.length);

        Cipher cipher = Cipher.getInstance(ALGORITHM);
        SecretKeySpec keySpec = new SecretKeySpec(SECRET_KEY, "AES");
        IvParameterSpec ivSpec = new IvParameterSpec(iv);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
        byte[] decrypted = cipher.doFinal(ciphertext);
        return new String(decrypted, "UTF-8");
    }

    @GetMapping("/health")
    public ResponseEntity<String> health() {
        return ResponseEntity.ok("OK");
    }
}

class TokenRequest {
    private String encryptedToken;
    public String getEncryptedToken() { return encryptedToken; }
    public void setEncryptedToken(String t) { this.encryptedToken = t; }
}

class TokenResponse {
    private String userId;
    private long issuedAt;
    public TokenResponse(String userId, long issuedAt) {
        this.userId = userId;
        this.issuedAt = issuedAt;
    }
    public String getUserId() { return userId; }
    public long getIssuedAt() { return issuedAt; }
}

class ErrorResponse {
    private String code;
    private String message;
    public ErrorResponse(String code, String message) {
        this.code = code;
        this.message = message;
    }
    public String getCode() { return code; }
    public String getMessage() { return message; }
}
